"use client";

import { useEffect, useState, type CSSProperties } from "react";

/**
 * Pixel-exact product thumbnails for the demo Shop/Inventory/Character screens.
 *
 * - `DecorThumb` crops one measured frame out of a shop atlas using
 *   `processed/shop-manifest.json` (generated by scripts/measure-shop-assets.ps1)
 *   — the same rectangles the Phaser scene renders, so the preview always
 *   matches the in-game artwork.
 * - `OutfitThumb` crops one 313 px cell from an outfit sheet (the sheets are
 *   the exact 1254 × 1254 / 4 × 4 layout verified by the shop guide and the
 *   measure script).
 *
 * Pure CSS sprites: no canvas, no extra downloads beyond the manifest JSON.
 */

export interface ManifestItem {
  id: string;
  /** Sheet path relative to public/assets/mailxp/shop/ (Windows separators). */
  sheet: string;
  sheetKey: string;
  x: number;
  y: number;
  w: number;
  h: number;
  sheetWidth: number;
  sheetHeight: number;
}

let manifestPromise: Promise<Record<string, ManifestItem>> | null = null;

/** Cached fetch of the shop manifest (one request per page load). */
export function loadShopManifest(): Promise<Record<string, ManifestItem>> {
  if (!manifestPromise) {
    manifestPromise = fetch("/assets/mailxp/processed/shop-manifest.json")
      .then((response) => {
        if (!response.ok) throw new Error(`shop-manifest.json HTTP ${response.status}`);
        return response.json() as Promise<{ items?: ManifestItem[] }>;
      })
      .then((data) => {
        const map: Record<string, ManifestItem> = {};
        for (const item of data.items ?? []) map[item.id] = item;
        return map;
      })
      .catch((error) => {
        manifestPromise = null; // allow a retry on the next render pass
        console.error("[MailXP] shop manifest load failed:", error);
        throw error;
      });
  }
  return manifestPromise;
}

const SHOP_ROOT = "/assets/mailxp/shop/";

/** Outfit sheets: exact 1254 × 1254, 4 × 4 grid of 313 px frames. */
const OUTFIT_SHEET = 1254;
const OUTFIT_FRAME = 313;

function sheetUrl(sheet: string): string {
  return SHOP_ROOT + sheet.split("\\").join("/");
}

interface ThumbProps {
  /** Square-ish preview box in CSS px. */
  box?: number;
  className?: string;
  /** Accessible name; omit when adjacent text already names the item. */
  label?: string;
}

/** One decor frame, scaled to fit a square box. */
export function DecorThumb({
  itemId,
  box = 64,
  className = "",
  label,
}: ThumbProps & { itemId: string }) {
  const [items, setItems] = useState<Record<string, ManifestItem> | null>(null);

  useEffect(() => {
    let live = true;
    loadShopManifest()
      .then((map) => {
        if (live) setItems(map);
      })
      .catch(() => {
        if (live) setItems({});
      });
    return () => {
      live = false;
    };
  }, []);

  const item = items?.[itemId];
  let style: CSSProperties;
  if (item) {
    const zoom = Math.min(box / item.w, box / item.h);
    style = {
      width: Math.round(item.w * zoom),
      height: Math.round(item.h * zoom),
      backgroundImage: `url(${sheetUrl(item.sheet)})`,
      backgroundSize: `${Math.round(item.sheetWidth * zoom)}px ${Math.round(item.sheetHeight * zoom)}px`,
      backgroundPosition: `${-Math.round(item.x * zoom)}px ${-Math.round(item.y * zoom)}px`,
      imageRendering: "pixelated",
    };
  } else {
    style = { width: box, height: box };
  }

  if (!item) {
    // Manifest not loaded yet (or failed): keep the layout slot honest —
    // an empty box is shown, never a wrong picture.
    return (
      <span
        aria-hidden={label ? undefined : true}
        aria-label={label}
        role={label ? "img" : undefined}
        className={`inline-block rounded border border-dashed border-[var(--mailxp-walnut)]/40 bg-white/40 ${className}`}
        style={{ width: box, height: box }}
      />
    );
  }

  return (
    <span
      aria-hidden={label ? undefined : true}
      aria-label={label}
      role={label ? "img" : undefined}
      className={`inline-block bg-no-repeat ${className}`}
      style={style}
    />
  );
}

/**
 * One outfit frame (default: idle-down, frame 0) from a 4 × 4 sheet.
 * `frame` is row-major: 0–3 down, 4–7 left, 8–11 right, 12–15 up.
 */
export function OutfitThumb({
  sheet,
  frame = 0,
  box = 64,
  className = "",
  label,
}: ThumbProps & { sheet: string; frame?: number }) {
  const zoom = box / OUTFIT_FRAME;
  const col = frame % 4;
  const row = Math.floor(frame / 4);
  const style: CSSProperties = {
    width: box,
    height: box,
    backgroundImage: `url(${sheet})`,
    backgroundSize: `${Math.round(OUTFIT_SHEET * zoom)}px ${Math.round(OUTFIT_SHEET * zoom)}px`,
    backgroundPosition: `${-Math.round(col * OUTFIT_FRAME * zoom)}px ${-Math.round(row * OUTFIT_FRAME * zoom)}px`,
    imageRendering: "pixelated",
  };

  return (
    <span
      aria-hidden={label ? undefined : true}
      aria-label={label}
      role={label ? "img" : undefined}
      className={`inline-block bg-no-repeat ${className}`}
      style={style}
    />
  );
}
